// Generated by `just generate` from `src/plugins/dotclaude/slices/asks/lab/asks.test.ts`. Edit the source and run `just generate`.
// The hook lab of the `asks` slice: `claude plugin test plugins/dotclaude` loads `hooks/register.ts`,
// fires `tool.check` events, and stubs each answer of Claude Code.
// The hook sits above the stub of the engine, so the stub answers `next(e)`, and the stubs of `fs` answer the reads.
// No command runs, no session starts, and no network call goes out.

import type { On } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

type Verdict = { decision: "allow" | "ask" | "deny"; reason?: string };

/** Stubs for one test: the verdict of the engine, the session, and the project folder. */
const stub = (on: On, verdict: Verdict = { decision: "allow" }): void => {
  on("tool.check", () => verdict);
  on("session.id", () => ({ value: "s1" }));
  on("session.cwd", () => ({ value: "/p" }));
  mock.env(on, { CLAUDE_PROJECT_DIR: "/p" });
};

/** Stubs the file system with `texts`: each path of `texts` is a file with that text. Gives each path that an `fs` event got. */
const project = (on: On, texts: Record<string, string> = {}): string[] => {
  const seen: string[] = [];
  // On Windows the engine can give a path with `\` and a drive letter, so the key drops both.
  const key = (p: string) => {
    seen.push(p);
    return p.replace(/\\/g, "/").replace(/^[A-Za-z]:/, "");
  };
  on("fs.exists", (_$, e) => ({ value: key(e.path) in texts }));
  on("fs.stat", (_$, e) => ({
    value: {
      kind: "file" as const,
      size: (texts[key(e.path)] ?? "").length,
      mtimeMs: 0,
      isLink: false,
    },
  }));
  on("fs.read", (_$, e) => ({ value: texts[key(e.path)] ?? "" }));
  return seen;
};

const TEST_FILE = "/p/tests/a.test.mjs";
const changeTest = ($: Engine) =>
  $.tool.check({
    tool: "Write",
    input: { file_path: TEST_FILE, content: "expect(1).toBe(2)\n" },
  });

test("a `Write` of a source file gets no ask", async ($: Engine, on: On) => {
  stub(on);
  project(on);
  const out = await $.tool.check({
    tool: "Write",
    input: { file_path: "/p/src/app.ts", content: "export const a = 1\n" },
  });
  expect(out.decision).toBe("allow");
});

test("a `Write` that changes a line of a test file asks", async ($: Engine, on: On) => {
  stub(on);
  const seen = project(on, { [TEST_FILE]: "expect(1).toBe(1)\n" });
  const out = await changeTest($);
  expect(out.decision, `fs paths: ${seen.join(", ")}`).toBe("ask");
  expect(out.reason?.length).toBeGreaterThan(0);
});

test("a `Bash` command that discards work asks, and a read-only one does not", async ($: Engine, on: On) => {
  stub(on);
  project(on);
  const stash = await $.tool.check({
    tool: "Bash",
    input: { command: "git stash" },
  });
  expect(stash.decision).toBe("ask");
  const status = await $.tool.check({
    tool: "Bash",
    input: { command: "git status" },
  });
  expect(status.decision).toBe("allow");
});

test("a deny of the engine stays a deny", async ($: Engine, on: On) => {
  stub(on, { decision: "deny", reason: "engine rule" });
  project(on, { [TEST_FILE]: "expect(1).toBe(1)\n" });
  const out = await changeTest($);
  expect(out.decision).toBe("deny");
});

test("an ask of the engine stays, and the reason of the slice joins it", async ($: Engine, on: On) => {
  stub(on, { decision: "ask", reason: "engine ask" });
  project(on, { [TEST_FILE]: "expect(1).toBe(1)\n" });
  const out = await changeTest($);
  expect(out.decision).toBe("ask");
  expect(out.reason).toContain("engine ask");
  expect(out.reason).toContain(TEST_FILE.replace("/p/", ""));
});

test("an ask of the engine stays when the slice has no ask", async ($: Engine, on: On) => {
  stub(on, { decision: "ask", reason: "engine ask" });
  project(on);
  const out = await $.tool.check({
    tool: "Write",
    input: { file_path: "/p/src/app.ts", content: "export const a = 1\n" },
  });
  expect(out.decision).toBe("ask");
  expect(out.reason).toBe("engine ask");
});
